const update = $json;
const message = update.message || update.edited_message || {};
const from = message.from || {};
const chat = message.chat || {};
const document = message.document;
const photos = message.photo || [];

const text = String(message.text || message.caption || '').trim();
const normalized = text.toLowerCase().replace(/\s+/g, ' ');

let incoming_type = 'text';
let has_file = false;
let file_id = null;
let file_name = null;
let file_type = null;
let mime_type = null;

if (document) {
  incoming_type = 'document';
  has_file = true;
  file_id = document.file_id || null;
  file_name = document.file_name || `telegram-document-${message.message_id || Date.now()}`;
  file_type = 'document';
  mime_type = document.mime_type || null;
} else if (photos.length > 0) {
  incoming_type = 'photo';
  has_file = true;
  const photo = photos[photos.length - 1];
  file_id = photo.file_id || null;
  file_name = `telegram-photo-${message.message_id || Date.now()}.jpg`;
  file_type = 'image';
  mime_type = 'image/jpeg';
}

return [{
  json: {
    user_id: String(from.id || ''),
    telegram_user_id: from.id,
    chat_id: chat.id,
    user_name: [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Telegram User',
    message_text: text,
    normalized_text: normalized,
    has_text: Boolean(text),
    incoming_type,
    has_file,
    file_id,
    file_name,
    file_type,
    mime_type,
    received_at: new Date().toISOString()
  },
  binary: $binary
}];

function norm(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9@._+-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function hasAny(text, phrases) {
  const normalizedText = norm(text);
  return phrases.some((phrase) => {
    const p = norm(phrase);
    return normalizedText === p || normalizedText.includes(p);
  });
}

function isOnlyGreeting(text, greetingPhrases) {
  const t = norm(text);
  return greetingPhrases.some((g) => t === norm(g));
}

function nowIso() {
  return new Date().toISOString();
}

function extractEmail(value) {
  const match = String(value || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return match ? match[0].toLowerCase() : '';
}

function isEmailCaptureRequest(text, normalizedText) {
  const raw = String(text || '');
  const normalized = String(normalizedText || '');

  return /^\/setemail\b/i.test(raw)
    || /\bmy email is\b/i.test(raw)
    || /^email\b/i.test(normalized)
    || (/^use\b/i.test(normalized) && raw.includes('@'));
}

function makeClaimId() {
  return `claim_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function rowUserId(row) {
  return String(
    row.User_ID ||
    row.user_id ||
    row.Telegram_ID ||
    row.telegram_user_id ||
    ''
  ).trim();
}

function productLabel(product, index) {
  return [
    `${index + 1}. ${product.Product_Name || 'Unnamed product'}`,
    `Brand: ${product.Brand || 'Not found'}`,
    `Warranty Valid Till: ${product.Warranty_Expiry_Date || 'Unknown'}`,
    `Status: ${product.Warranty_Status || 'Unknown'}`,
    `Invoice Number: ${product.Invoice_Number || 'Not found'}`
  ].join('\n');
}

function compactProduct(product, index) {
  return `${index + 1}. ${product.Product_Name || 'Unnamed product'} - ${product.Brand || 'Not found'} - ${product.Warranty_Status || 'Unknown'}`;
}

function parseStateDate(row) {
  const raw = String(
    row.Last_Updated ||
    row.Updated_At ||
    row.Created_At ||
    row.created_at ||
    ''
  ).trim();

  if (!raw) return 0;

  const isoParsed = new Date(raw);
  if (!Number.isNaN(isoParsed.getTime())) return isoParsed.getTime();

  const dmyTime = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})(?:\s+(\d{1,2}):(\d{2}))?/);
  if (dmyTime) {
    const parsed = new Date(
      Number(dmyTime[3]),
      Number(dmyTime[2]) - 1,
      Number(dmyTime[1]),
      Number(dmyTime[4] || 0),
      Number(dmyTime[5] || 0)
    );

    if (!Number.isNaN(parsed.getTime())) return parsed.getTime();
  }

  return 0;
}

function getLatestState(stateRows) {
  if (!stateRows.length) return {};

  const withIndex = stateRows.map((row, index) => ({
    row,
    index,
    ts: parseStateDate(row)
  }));

  return withIndex
    .sort((a, b) => {
      if (b.ts !== a.ts) return b.ts - a.ts;
      return b.index - a.index;
    })[0].row;
}

function getNodeJson(nodeNames) {
  for (const nodeName of nodeNames) {
    try {
      const nodeData = $node[nodeName]?.json;
      if (nodeData && Object.keys(nodeData).length > 0) return nodeData;
    } catch (error) {
      // Try next node name
    }
  }

  return {};
}

function getItemsFromFirstAvailableNode(nodeNames) {
  for (const nodeName of nodeNames) {
    try {
      const items = $items(nodeName);
      if (Array.isArray(items)) {
        return items.map((item) => item.json || {});
      }
    } catch (error) {
      // Try next possible node name
    }
  }

  return [];
}

function matchProducts(products, messageText) {
  const normalizedMessage = norm(messageText);

  const stop = [
    'claim',
    'warranty',
    'raise',
    'replacement',
    'repair',
    'not',
    'working',
    'issue',
    'with',
    'problem',
    'my',
    'the',
    'for',
    'please',
    'product',
    'want',
    'to',
    'i'
  ];

  const terms = normalizedMessage
    .split(' ')
    .filter((term) => term.length >= 2 && !stop.includes(term));

  return products
    .map((product) => {
      const productName = norm(product.Product_Name);
      const brand = norm(product.Brand);
      const category = norm(product.Category);
      const seller = norm(product.Seller);
      const invoice = norm(product.Invoice_Number);

      const haystack = [productName, brand, category, seller, invoice]
        .filter(Boolean)
        .join(' ');

      let score = 0;

      if (productName && normalizedMessage.includes(productName)) score += 8;
      if (invoice && normalizedMessage.includes(invoice)) score += 8;
      if (brand && normalizedMessage.includes(brand)) score += 4;
      if (category && normalizedMessage.includes(category)) score += 1;

      for (const term of terms) {
        if (productName.split(' ').includes(term)) score += 3;
        else if (brand.split(' ').includes(term)) score += 3;
        else if (haystack.includes(term)) score += 1;
      }

      return { product, score };
    })
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score);
}

function coverageText(product, issue) {
  const category = product.Category || 'product';
  const status = product.Warranty_Status || 'Unknown';
  const issueText = norm(issue);

  const accidentalTerms = [
    'broken',
    'crack',
    'cracked',
    'water',
    'liquid',
    'dropped',
    'physical damage',
    'burnt',
    'burn',
    'accident'
  ];

  const accidental = accidentalTerms.some((term) =>
    issueText.includes(norm(term))
  );

  if (accidental) {
    return `This may not be covered if it is accidental or physical damage. Since the ${category} warranty status is ${status}, it may still be worth asking support to review it.`;
  }

  if (status === 'Active' || status === 'Expiring Soon') {
    return `This appears likely to be worth raising as a warranty claim based on the ${category} warranty status: ${status}.`;
  }

  return `This may be difficult to claim because the warranty status is ${status}. You can still ask support to confirm.`;
}

function buildClaimEmailBody(product, issue) {
  return [
    'Dear Support Team,',
    '',
    'I would like to raise a warranty claim for the following product:',
    '',
    `Product Name: ${product.Product_Name || ''}`,
    `Brand: ${product.Brand || ''}`,
    `Category: ${product.Category || ''}`,
    `Invoice Number: ${product.Invoice_Number || ''}`,
    `Purchase Date: ${product.Purchase_Date || ''}`,
    `Seller: ${product.Seller || ''}`,
    `Warranty Valid Till: ${product.Warranty_Expiry_Date || ''}`,
    '',
    'Issue:',
    issue,
    '',
    'The product may be eligible for warranty support based on the saved warranty information. Please review the request and guide me on the next steps for repair, replacement, or service under warranty.',
    '',
    'Regards'
  ].join('\n');
}

function isValidIssueDescription(text, greetingPhrases) {
  const clean = String(text || '').trim();

  if (!clean) return false;
  if (isOnlyGreeting(clean, greetingPhrases)) return false;
  if (clean.length < 12) return false;

  return true;
}

// MAIN INPUT
const input = getNodeJson([
  'Normalize Telegram Message',
  'Normalize Telegram Message1',
  'Normalize Telegram Message2',
  'Normalize Telegram Message3'
]);

const userId = String(input.user_id || input.telegram_user_id || '').trim();
const telegramUserId = String(input.telegram_user_id || input.user_id || userId || '').trim();
const chatId = String(input.chat_id || '').trim();
const text = String(input.message_text || '').trim();
const ntext = String(input.normalized_text || norm(text)).trim();

// SHEET ROWS
const stateRows = getItemsFromFirstAvailableNode([
  'Read Conversation_State tab',
  'Read Conversation_State tab1',
  'Read Conversation_State tab2',
  'Read Conversation_State tab3'
]).filter((row) => rowUserId(row) === userId);

const products = getItemsFromFirstAvailableNode([
  'Read Products tab',
  'Read Products tab1',
  'Read Products tab2',
  'Read Products tab3'
]).filter((row) => rowUserId(row) === userId);

const claims = getItemsFromFirstAvailableNode([
  'Read Claims tab',
  'Read Claims tab1',
  'Read Claims tab2',
  'Read Claims tab3'
]).filter((row) => rowUserId(row) === userId);

const state = getLatestState(stateRows);

const waitingFor = String(state.Bot_Waiting_For || '').trim();
const relatedProductId = String(state.Related_Product_ID || '').trim();
const relatedClaimId = String(state.Related_Claim_ID || '').trim();

const productById = products.find((product) =>
  String(product.Product_ID || '').trim() === relatedProductId
);

let intent = 'unknown';
let route_index = 0;
let reply_text = '';

let claim_id = relatedClaimId || '';
let claim_status = '';
let user_approval_status = '';

let related_product_id = relatedProductId || '';
let related_claim_id = relatedClaimId || '';

let bot_waiting_for = '';
let current_step = '';
let next_action = '';
let notes = '';

let issue_description = '';
let claim_email_to = '';
let claim_email_subject = '';
let claim_email_body = '';
let user_email = '';

const approvalPhrases = ['send', 'approve', 'yes send', 'confirm send'];
const cancelPhrases = ['cancel', 'stop', 'do not send'];
const helpPhrases = ['/start', 'help', 'what can you do', 'how does this work'];
const uploadPhrases = [
  'how to upload bill',
  'what format',
  'can i send pdf',
  'upload invoice',
  'upload bill',
  'send pdf'
];
const warrantyPhrases = ['show my warranties', 'my warranties', 'my products', '/mywarranties'];
const claimStatusPhrases = ['show my claims', 'claim status', 'status of my claim'];
const followupPhrases = ['follow up', 'send follow up', 'any update'];
const claimPhrases = [
  'warranty claim',
  'raise claim',
  'replacement',
  'repair',
  'not working',
  'issue with',
  'problem with',
  'claim'
];
const greetingPhrases = ['hi', 'hii', 'hey', 'hello', 'yo', 'ok', 'okay', 'thanks', 'thank you'];

const extractedEmail = extractEmail(text);
const emailCaptureRequested = isEmailCaptureRequest(text, ntext);

// INTENT DETECTION
if (input.has_file) {
  intent = 'document_upload';
  route_index = 5;
  reply_text = 'Processing your document now.';
} else if (emailCaptureRequested) {
  intent = 'email_capture';
  user_email = extractedEmail;

  if (user_email) {
    route_index = 6;
    reply_text = 'Email saved. I will CC this email when sending approved claim emails.';
  } else {
    route_index = 0;
    reply_text = 'Please send your email like this: /setemail yourname@example.com';
  }
} else if (!input.has_text) {
  intent = 'upload_guidance';
} else if (
  waitingFor === 'claim_approval' &&
  hasAny(ntext, approvalPhrases)
) {
  intent = 'claim_approval';
} else if (
  waitingFor === 'claim_approval' &&
  hasAny(ntext, cancelPhrases)
) {
  intent = 'claim_cancel';
} else if (
  waitingFor === 'claim_approval' &&
  input.has_text &&
  !hasAny(ntext, approvalPhrases) &&
  !hasAny(ntext, cancelPhrases)
) {
  intent = 'awaiting_claim_approval_response';
} else if (
  waitingFor === 'issue_description' &&
  input.has_text &&
  !hasAny(ntext, helpPhrases) &&
  !hasAny(ntext, cancelPhrases) &&
  isValidIssueDescription(text, greetingPhrases)
) {
  intent = 'issue_description';
} else if (
  waitingFor === 'issue_description' &&
  input.has_text &&
  !isValidIssueDescription(text, greetingPhrases)
) {
  intent = 'invalid_issue_description';
} else if (hasAny(ntext, cancelPhrases)) {
  intent = 'claim_cancel';
} else if (hasAny(ntext, helpPhrases)) {
  intent = 'help';
} else if (hasAny(ntext, uploadPhrases)) {
  intent = 'upload_guidance';
} else if (hasAny(ntext, warrantyPhrases)) {
  intent = 'warranty_lookup';
} else if (hasAny(ntext, claimStatusPhrases)) {
  intent = 'claim_status';
} else if (hasAny(ntext, followupPhrases)) {
  intent = 'follow_up_request';
} else if (hasAny(ntext, approvalPhrases)) {
  intent = 'claim_approval';
} else if (hasAny(ntext, claimPhrases)) {
  intent = 'claim_request';
} else if (isOnlyGreeting(text, greetingPhrases)) {
  intent = 'help';
}

// INTENT HANDLING
if (intent === 'document_upload') {
  reply_text = reply_text || 'Processing your document now.';
} else if (intent === 'help') {
  reply_text = [
    'I can help you:',
    '1. Save bills, invoices, warranty cards, and demo insurance policies.',
    '2. Show your saved warranties.',
    '3. Start a warranty claim draft.',
    '',
    'Upload a clear bill/photo/PDF, or type show my warranties.'
  ].join('\n');
} else if (intent === 'upload_guidance') {
  reply_text = 'Upload a clear PDF, JPG, or PNG bill, invoice, warranty card, or insurance policy. Make sure product name, purchase date, seller, and warranty details are readable.';
} else if (intent === 'email_capture') {
  reply_text = user_email
    ? 'Email saved. I will CC this email when sending approved claim emails.'
    : 'Please send your email like this: /setemail yourname@example.com';
} else if (intent === 'warranty_lookup') {
  if (products.length === 0) {
    reply_text = 'No saved warranties found yet. Upload a bill or warranty card first.';
  } else {
    reply_text = `Your saved warranties:\n\n${products
      .slice(0, 10)
      .map(productLabel)
      .join('\n\n')}`;
  }
} else if (intent === 'claim_request') {
  const matches = matchProducts(products, text);

  if (products.length === 0) {
    reply_text = 'No saved warranties found yet. Upload a bill or warranty card first.';
  } else if (matches.length === 0) {
    reply_text = [
      'I could not match that claim request to a saved product.',
      '',
      'Your saved products:',
      products.slice(0, 10).map(compactProduct).join('\n'),
      '',
      'Please send: claim PRODUCT NAME'
    ].join('\n');
  } else {
    const bestScore = matches[0].score;
    const bestMatches = matches.filter((entry) => entry.score === bestScore);

    if (bestMatches.length > 1 && bestScore < 8) {
      reply_text = [
        'I found multiple matching products:',
        '',
        bestMatches
          .slice(0, 10)
          .map((entry, index) => compactProduct(entry.product, index))
          .join('\n'),
        '',
        'Please be more specific. Send: claim PRODUCT NAME'
      ].join('\n');
    } else {
      const product = matches[0].product;

      related_product_id = product.Product_ID || '';
      related_claim_id = '';

      route_index = 1;
      bot_waiting_for = 'issue_description';
      current_step = 'waiting_for_issue_description';
      next_action = 'Ask user for issue description';

      reply_text = [
        'I found this product:',
        '',
        `Product: ${product.Product_Name || 'Unnamed product'}`,
        `Brand: ${product.Brand || 'Not found'}`,
        `Warranty Valid Till: ${product.Warranty_Expiry_Date || 'Unknown'}`,
        `Status: ${product.Warranty_Status || 'Unknown'}`,
        `Support Email: ${product.Support_Email || 'Not found'}`,
        '',
        'Please describe the issue in one sentence.',
        'Example: Battery is not holding charge properly.'
      ].join('\n');
    }
  }
} else if (intent === 'invalid_issue_description') {
  route_index = 0;
  reply_text = 'Please describe the actual product issue in one sentence. Example: Battery is not holding charge properly.';
} else if (intent === 'issue_description') {
  const product = productById;

  if (!product) {
    route_index = 1;
    reply_text = 'I lost the product context. Please send: claim PRODUCT NAME';
    current_step = 'needs_product_selection';
    bot_waiting_for = '';
    related_product_id = '';
    related_claim_id = '';
  } else {
    route_index = 2;

    claim_id = makeClaimId();
    related_claim_id = claim_id;
    related_product_id = product.Product_ID || '';

    issue_description = text;
    claim_email_to = product.Support_Email || '';
    claim_email_subject = `Warranty Claim Request for ${product.Product_Name || 'Product'} - Invoice No. ${product.Invoice_Number || 'Not Available'}`;
    claim_email_body = buildClaimEmailBody(product, text);

    claim_status = 'Draft Created';
    user_approval_status = 'Pending';

    bot_waiting_for = 'claim_approval';
    current_step = 'waiting_for_claim_approval';
    next_action = 'Awaiting user approval';
    notes = 'Created from Telegram chat router';

    reply_text = [
      coverageText(product, text),
      '',
      `Claim draft created for ${product.Product_Name || 'this product'}.`,
      `Support Email: ${claim_email_to || 'Not found'}`,
      `Issue: ${text}`,
      '',
      'Reply SEND to send this email, or CANCEL to stop.'
    ].join('\n');
  }
} else if (intent === 'awaiting_claim_approval_response') {
  route_index = 0;
  reply_text = 'A claim draft is already ready. Please reply SEND to send the claim email, or CANCEL to stop.';
} else if (intent === 'claim_approval') {
  if (!relatedClaimId) {
    route_index = 0;
    reply_text = 'I do not see a claim waiting for approval. Start with: claim PRODUCT NAME';
  } else {
    route_index = 3;

    claim_id = relatedClaimId;
    related_claim_id = relatedClaimId;
    related_product_id = relatedProductId;

    claim_status = 'Approved for Sending';
    user_approval_status = 'Approved';

    bot_waiting_for = 'email_send_workflow';
    current_step = 'approved_for_sending';
    next_action = 'Email sending workflow should send claim email';

    reply_text = 'Approval received. The email sending workflow will now send the claim email.';
  }
} else if (intent === 'claim_cancel') {
  if (!relatedClaimId) {
    route_index = 1;

    bot_waiting_for = '';
    current_step = 'cancelled';
    next_action = '';
    related_product_id = '';
    related_claim_id = '';

    reply_text = 'Claim cancelled.';
  } else {
    route_index = 4;

    claim_id = relatedClaimId;
    related_claim_id = relatedClaimId;
    related_product_id = relatedProductId;

    claim_status = 'Cancelled';
    user_approval_status = 'Cancelled';

    bot_waiting_for = '';
    current_step = 'cancelled';
    next_action = '';

    reply_text = 'Claim cancelled.';
  }
} else if (intent === 'claim_status') {
  if (claims.length === 0) {
    reply_text = 'No claim requests found yet.';
  } else {
    reply_text = `Recent claims:\n\n${claims
      .slice(-5)
      .reverse()
      .map((claim, index) => {
        return [
          `${index + 1}. Claim ${claim.Claim_ID || ''}`,
          `Status: ${claim.Claim_Status || 'Unknown'}`,
          `Next Action: ${claim.Next_Action || 'None'}`
        ].join('\n');
      })
      .join('\n\n')}`;
  }
} else if (intent === 'follow_up_request') {
  reply_text = 'Follow-up support will be handled after a claim email has been sent. For now, use claim status to check the latest saved status.';
} else {
  reply_text = "I can help you upload bills, check warranties, and raise claims. Send a bill/photo/PDF or type 'show my warranties'.";
}

return [
  {
    json: {
      ...input,

      user_id: String(userId || ''),
      telegram_user_id: String(telegramUserId || ''),
      chat_id: String(chatId || ''),
      user_name: String(input.user_name || ''),

      intent: String(intent || ''),
      route_index,
      reply_text: String(reply_text || ''),

      claim_id: String(claim_id || ''),
      related_product_id: String(related_product_id || ''),
      related_claim_id: String(related_claim_id || ''),

      bot_waiting_for: String(bot_waiting_for || ''),
      current_step: String(current_step || ''),
      next_action: String(next_action || ''),

      issue_description: String(issue_description || ''),
      claim_email_to: String(claim_email_to || ''),
      claim_email_subject: String(claim_email_subject || ''),
      claim_email_body: String(claim_email_body || ''),

      claim_status: String(claim_status || ''),
      user_approval_status: String(user_approval_status || ''),

      last_message: String(text || ''),
      updated_at: String(nowIso() || ''),
      notes: String(notes || ''),
      user_email: String(user_email || ''),

      debug_waiting_for_before: String(waitingFor || ''),
      debug_state_product_id_before: String(relatedProductId || ''),
      debug_state_claim_id_before: String(relatedClaimId || ''),
      debug_state_rows_found: String(stateRows.length || 0),
      debug_products_found: String(products.length || 0),
      debug_claims_found: String(claims.length || 0)
    }
  }
];

const text = String($json.reply_text || '').trim() || "I can help you upload bills, check warranties, and raise claims. Send a bill/photo/PDF or type 'show my warranties'.";
const routeStatuses = {
  0: 'direct_response',
  1: 'state_update_pending',
  2: 'claim_draft_pending',
  3: 'approval_pending_email_send',
  4: 'claim_cancel_pending',
  5: 'document_intake_requested',
  6: 'email_capture_pending'
};
const status = $json.status || routeStatuses[Number($json.route_index)] || 'routed';

return [{
  json: {
    ...$json,
    reply_text: text.length > 3900 ? `${text.slice(0, 3850)}\n\nMessage shortened.` : text,
    status
  }
}];
